class Solution:
    def allowRequests(self, requests, limit, window):
        accepted = {}  # client -> every accepted timestamp, ever
        out = []
        for t, client in requests:
            times = accepted.setdefault(client, [])
            recent = sum(1 for s in times if s > t - window)
            ok = recent < limit
            if ok:
                times.append(t)
            out.append(ok)
        return out

