            List<Integer> times = accepted.computeIfAbsent(r[1], c -> new ArrayList<>());
            int recent = 0;
            for (int s : times) if (s > t - window) recent++;
            boolean ok = recent < limit;
            if (ok) times.add(t);
            out.add(ok);
        }
        return out;
    }
}

