from collections import defaultdict, deque


class Solution:
    def allowRequests(self, requests, limit, window):
        log = defaultdict(deque)  # client -> accepted timestamps still in the window
        out = []
        for t, client in requests:
            q = log[client]
            while q and q[0] <= t - window:
                q.popleft()  # aged out for good
            if len(q) < limit:
                q.append(t)
                out.append(True)
            else:
                out.append(False)  # rejected requests are not recorded
        return out

