import java.util.*;

class Solution {
    public List<Boolean> allowRequests(int[][] requests, int limit, int window) {
        Map<Integer, ArrayDeque<Integer>> log = new HashMap<>(); // client -> accepted timestamps in the window
        List<Boolean> out = new ArrayList<>();
        for (int[] r : requests) {
            int t = r[0];
            ArrayDeque<Integer> q = log.computeIfAbsent(r[1], c -> new ArrayDeque<>());
            while (!q.isEmpty() && q.peekFirst() <= t - window) q.pollFirst();
            if (q.size() < limit) {
                q.offerLast(t);
                out.add(true);
            } else {
                out.add(false); // rejected requests are not recorded
            }
        }
        return out;
    }
}

