func allowRequests(requests [][]int, limit int, window int) []bool {
	log := map[int][]int{} // client -> accepted timestamps still in the window
	out := []bool{}
	for _, r := range requests {
		t, client := r[0], r[1]
		q := log[client]
		for len(q) > 0 && q[0] <= t-window {
			q = q[1:]
		}
		if len(q) < limit {
			q = append(q, t)
			out = append(out, true)
		} else {
			out = append(out, false) // rejected requests are not recorded
		}
		log[client] = q
	}
	return out
}

