var countInWindows = function(hits, queries) {
    // first index whose hit is >= x (strict: > x)
    const firstAt = (x, strict) => {
        let lo = 0, hi = hits.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (hits[mid] < x || (strict && hits[mid] === x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };
    return queries.map(([start, end]) => firstAt(end, true) - firstAt(start, false));
};

