class Solution {
    public int[] countInWindows(int[] hits, int[][] queries) {
        int[] out = new int[queries.length];
        for (int i = 0; i < queries.length; i++)
            out[i] = firstAt(hits, queries[i][1], true) - firstAt(hits, queries[i][0], false);
        return out;
    }

    // first index whose hit is >= x (strict: > x)
    private int firstAt(int[] hits, int x, boolean strict) {
        int lo = 0, hi = hits.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (hits[mid] < x || (strict && hits[mid] == x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

