import "sort"

func countInWindows(hits []int, queries [][]int) []int {
	out := make([]int, len(queries))
	for i, q := range queries {
		lo := sort.SearchInts(hits, q[0]) // first hit >= start
		hi := sort.Search(len(hits), func(j int) bool { return hits[j] > q[1] }) // first hit > end
		out[i] = hi - lo
	}
	return out
}

